        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    fib = [0, 1]
    count = 0
    while count < n:
        fib.append(fib[-1] + fib[-2])
        if is_prime(fib[-1]):
            count += 1
    return fib[-1]

from itertools import combinations

def triples_sum_to_zero(l: list):
    for triple in combinations(l, 3):
        if sum(triple) == 0:
            return True
    return False

def pairs_sum_to_zero(l):
    s = set(l)
    for i in s:
        if -i in s and i != 0:
            return True
    return False

def change_base(x: int, base: int) -> str:
    if x == 0:
        return '0'
    digits = []
    while x:
        digits.append(str(x % base))
        x //= base
    digits.reverse()
    return ''.join(digits)

def fib4(n: int) -> int:
