from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    seen = set()
    seen_more_than_once = set()
    result = []
    for num in numbers:
        if num in seen_more_than_once:
            continue
        if num in seen:
            seen_more_than_once.add(num)
            result.remove(num)
        else:
            seen.add(num)
            result.append(num)
    return result

