def skjkasdkd(lst):
    mx = 0
    for x in lst:
        if x <= 1:
            continue
        i = 2
        while i * i <= x:
            if x % i == 0:
                break
            i += 1
        if i * i > x:
            mx = max(mx, x)
    sm = 0
    while mx > 0:
        sm += mx % 10
        mx //= 10
    return sm
```

